## 安全方案：三层校验 + 自动回退全量读取

```rust
use std::fs::File;
use std::io::{BufRead, BufReader, Seek, SeekFrom};
use std::path::Path;

pub struct FileReadState {
    pub last_size: u64,
    pub last_mtime: i64,
    pub header_fingerprint: String, // 比如 session header 的 id
}

/// 安全地增量读取 JSONL
/// 
/// 返回值：
/// - Ok(new_size)           → 增量读取成功
/// - Err("fallback")        → 检测到非追加写入，需要全量重读
pub fn safe_append_only_read(
    path: &Path,
    state: &FileReadState,
    existing_entries: &mut Vec<SessionEntry>,
) -> Result<u64, String> {
    let metadata = std::fs::metadata(path)
        .map_err(|e| format!("stat failed: {}", e))?;

    let current_size = metadata.len();
    let current_mtime = metadata.modified()
        .ok()
        .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);

    // ═══════════════════════════════════════════════════════
    // 第一层：文件被 truncate / rewrite 了（size 变小或不变但 mtime 变了）
    // ═══════════════════════════════════════════════════════
    if current_size < state.last_size {
        return Err("fallback".to_string()); // 文件被截断了
    }

    if current_size == state.last_size && current_mtime != state.last_mtime {
        // size 一样但 mtime 变了 = 原地重写（比如 compaction）
        return Err("fallback".to_string());
    }

    if current_size == state.last_size {
        return Ok(state.last_size); // 真的没变
    }

    // ═══════════════════════════════════════════════════════
    // 第二层：校验文件头部身份没变（防止整个文件被替换为同名不同内容）
    // ═══════════════════════════════════════════════════════
    let header_valid = verify_header_fingerprint(path, &state.header_fingerprint)?;
    if !header_valid {
        return Err("fallback".to_string()); // 文件被整体替换了
    }

    // ═══════════════════════════════════════════════════════
    // 第三层：seek 到上次位置，尝试解析新增的第一行
    // ═══════════════════════════════════════════════════════
    let mut file = File::open(path)
        .map_err(|e| format!("open failed: {}", e))?;

    file.seek(SeekFrom::Start(state.last_size))
        .map_err(|e| format!("seek failed: {}", e))?;

    let mut reader = BufReader::new(file);
    let mut first_new_line = String::new();

    // 读新增部分的第一行
    let n = reader.read_line(&mut first_new_line)
        .map_err(|e| format!("read failed: {}", e))?;

    if n == 0 {
        // 没有新内容（可能是 touch）
        return Ok(state.last_size);
    }

    // ═══════════════════════════════════════════════════════
    // 关键校验：新增部分的第一行必须是合法的完整 JSON
    // 如果中间被篡改过，seek 过去大概率会落到某行的中间，
    // 导致 JSON parse 失败，这时我们就知道"前面被改了"
    // ═══════════════════════════════════════════════════════
    let trimmed = first_new_line.trim();
    if trimmed.is_empty() {
        // 空行，继续读下一行
    } else if serde_json::from_str::<serde_json::Value>(trimmed).is_err() {
        // 解析失败！说明 offset 错位了，前面一定被修改过
        return Err("fallback".to_string());
    }

    // 解析成功，说明 offset 是对的。继续解析剩余的新行
    let mut new_entries = vec![];
    if !trimmed.is_empty() {
        new_entries.push(serde_json::from_str(trimmed).map_err(|e| e.to_string())?);
    }

    let mut line = String::new();
    loop {
        line.clear();
        let n = reader.read_line(&mut line).map_err(|e| e.to_string())?;
        if n == 0 { break; }
        let trimmed = line.trim();
        if trimmed.is_empty() { continue; }
        new_entries.push(serde_json::from_str(trimmed).map_err(|e| e.to_string())?);
    }

    // 追加到已有 entries
    existing_entries.extend(new_entries);

    Ok(current_size)
}
```

