            .query_map([], |row| row.get(1))
            .map_err(|e| format!("Failed to query columns for {table}: {e}"))?
            .collect::<Result<Vec<_>, _>>()
            .map_err(|e| format!("Failed to collect columns for {table}: {e}"))?;
        Ok(column_names.iter().any(|name| name == column))
